import backtrader as bt


class CSILiteMomentum(bt.Strategy):
    def __init__(self):
        self.atr = bt.indicators.ATR(self.data, period=14)
        self.macd = bt.indicators.MACDHisto(
            self.data,
            period_me1=12,
            period_me2=26,
            period_signal=9,
        )
        self.price_sma = bt.indicators.SMA(self.data.close, period=50)
        self.atr_sma = bt.indicators.SMA(self.atr, period=50)
        self.volume_sma = bt.indicators.SMA(self.data.volume, period=50)
        self.rsi = bt.indicators.RSI(self.data.close, period=14)
        self.order = None
        self.tranches = 0
        self.peak_score = None

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                self.tranches += 1
            else:
                self.tranches = 0
                self.peak_score = None

        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None

    def next(self):
        if self.order:
            return

        score = (
            max(0.0, self.macd.histo[0])
            * (self.atr[0] / self.atr_sma[0])
            * (self.data.volume[0] / self.volume_sma[0])
            * 100.0
        )

        if self.position:
            if self.peak_score is None:
                self.peak_score = score
            else:
                self.peak_score = max(self.peak_score, score)

            macd_crossed_below = (
                self.macd.macd[0] < self.macd.signal[0]
                and self.macd.macd[-1] >= self.macd.signal[-1]
            )
            if (
                score < 0.70 * self.peak_score
                or macd_crossed_below
                or self.rsi[0] < 45.0
            ):
                self.order = self.close()
                return

        entry_signal = (
            score > 1.5
            and self.data.close[0] > self.price_sma[0]
            and self.macd.macd[0] > self.macd.signal[0]
        )
        capital = self.broker.getvalue()
        exposure = abs(self.position.size * self.data.close[0])
        if entry_signal and self.tranches < 3 and exposure < 0.50 * capital:
            size = 0.05 * capital / self.data.close[0]
            self.order = self.buy(size=size)
            if not self.position:
                self.peak_score = score
